      de: ["Gegründet im Jahr 1825 als Festung Pischpek.", "Trug von 1926 bis 1991 den Namen Frunze.", "Liegt auf einer durchschnittlichen Höhe von 800 Metern.", "Die Einwohnerzahl überstieg 2020 die Marke von 1 Million.", "Bischkek ist bekannt als eine der grünsten Städte der ehemaligen Sowjetunion.", "Der Ala-Archa-Nationalpark liegt nur 40 km südlich der Stadt.", "Das Stadtgebiet umfasst eine Fläche von etwa 127 Quadratkilometern.", "Der Name Bischkek bezieht sich auf einen traditionellen Kumys-Rührer."],
