      en: ["The highest provincial capital in Kyrgyzstan (2020 m).", "Founded in 1868 as a Russian garrison on the Silk Road.", "The Naryn River divides the city into two halves.", "Known for extremely cold winters, reaching down to -40 degrees.", "Home to a campus of the University of Central Asia.", "The town is nearly 15 km long but often only a few hundred metres wide.", "A key base for cross-border trade with China."],
