      en: ["Served as the capital of the Karakhanid Empire in the 11th century.", "Features three perfectly preserved medieval mausoleums.", "The Uzgen Minaret is one of the oldest in the country.", "Famous for the production of red Devzira rice.", "Boasts a history stretching back over 2000 years.", "The majority of the population belongs to the Uzbek minority.", "Located on the banks of the Kara Darya River in the Fergana Valley."],
      es: ["Fue la capital del Imperio Carajánida en el siglo XI.", "Posee tres mausoleos medievales perfectamente conservados.", "El minarete de Uzgen es uno de los más antiguos del país.", "Es famosa por la producción de arroz rojo Devzira.", "Tiene una historia de más de 2000 años.", "La mayoría de la población pertenece a la minoría uzbeka.", "Se encuentra a orillas del río Kara Darya, en el valle de Fergana."],
      pt: ["Foi a capital do Império Caranída no século XI.", "Possui três mausoléus medievais perfeitamente preservados.", "O minarete de Uzgen é um dos mais antigos do país.", "É famosa pela produção de arroz vermelho Devzira.", "Possui uma história de mais de 2000 anos.", "A maioria da população pertence à minoria uzbeque.", "Localiza-se nas margens do rio Kara Darya, no vale de Fergana."],
      fr: ["Fut la capitale de l'empire Qarakhanide au XIe siècle.", "Possède trois mausolées médiévaux parfaitement conservés.", "Le minaret d'Uzgen est l'un des plus anciens du pays.", "Est célèbre pour la production de riz rouge Devzira.", "Bénéficie d'une histoire de plus de 2000 ans.", "La majorité de la population appartient à la minorité ouzbèke.", "Située sur les rives de la rivière Kara Darya dans la vallée de Ferghana."],
