      es: ["Fue nombrada centro de una provincia recién creada en 1999.", "La zona es conocida por sus albaricoques secos."],
      pt: ["Foi nomeada centro de uma província recém-criada em 1999.", "A região é conhecida pelos seus damascos secos."],
      fr: ["Est devenue le centre d'une province nouvellement créée en 1999.", "La région est réputée pour ses abricots secs."],
