      es: ["Antiguamente el asentamiento se llamaba Karavan.", "Recibió oficialmente el estatus de ciudad en el año 2004."],
      pt: ["Antigamente o assentamento chamava-se Karavan.", "Recebeu oficialmente o estatuto de cidade no ano de 2004."],
      fr: ["L'établissement s'appelait autrefois Karavan.", "A officiellement reçu le statut de ville en 2004."],
