      es: ["Llamada así por Duishonkul Shopokov, un héroe de la Segunda Guerra Mundial.", "Se llamó Novotroitskoye hasta 1967."],
      pt: ["Chamada assim por Duishonkul Shopokov, um herói da Segunda Guerra Mundial.", "Chamava-se Novotroitskoye até 1967."],
