      en: ["Named after Duishenkul Shopokov, a hero of World War II.", "A significant industrial centre near the town of Sokuluk.", "Formerly known as Krasnooktyabrsky (Red October).", "Home to large factories manufacturing agricultural machinery.", "Attained city status in 1985.", "The majority of jobs are in mechanical engineering and the food industry.", "The city is conveniently located along the Bishkek–Osh railway line."],
