      ro: ["Fondat în 1912 sub numele Bystrovka ca așezare rusă.", "Situat pe râul Chu, la intrarea în defileul Boom.", "A fost un centru important de minerit pentru metale rare în timpul URSS.", "A primit oficial statutul de oraș abia în anul 2012.", "Economia este dominată astăzi de agricultură și mica industrie.", "O oprire importantă pentru călătorii care merg spre lacul Issyk-Kul.", "Găzduiește o stație electrică majoră, critică pentru rețeaua națională."],
