      pt: ["Foi fundada em 1912 como o assentamento russo de Bystrovka.", "Situa-se junto ao rio Chu, à entrada do desfiladeiro de Boom.", "Durante a URSS foi um importante centro mineiro de metais raros.", "Só foi oficialmente nomeada cidade em 2012.", "A economia atual é marcada pela agricultura e pequena indústria.", "Serve como paragem importante para os viajantes que vão para o lago Issyk-Kul.", "Abriga uma grande subestação elétrica crítica para a rede nacional."],
      fr: ["A été fondée en 1912 en tant qu'établissement russe sous le nom de Bystrovka.", "Située sur la rivière Tchou, à l'entrée de la gorge de Boom.", "Était un centre minier important pour les métaux rares à l'époque de l'URSS.", "N'a été officiellement nommée ville qu'en 2012.", "L'économie est aujourd'hui marquée par l'agriculture et la petite industrie.", "Sert d'étape importante pour les voyageurs en route vers le lac Issyk-Kul.", "Abrite un grand poste électrique critique pour le réseau national."],
